import numpy as np

# MECHANISM: Use a piecewise linear function with different slopes for different remaining capacities

def priority(item, bins):
    max_capacity = 150
    scores = np.zeros_like(bins)
    thresholds = np.array([75, 100])
    slopes = np.array([10, 5, 1])

    for i, capacity in enumerate(bins):
        if capacity >= thresholds[1]:
            scores[i] = capacity - item
        elif capacity >= thresholds[0]:
            scores[i] = thresholds[1] - item + (capacity - thresholds[0]) * slopes[1]
        else:
            scores[i] = thresholds[0] - item + (capacity - thresholds[0]) * slopes[2]

    return scores
